import java.io.*;
import java.util.Scanner;
public class JWorkHours2 {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        System.out.println("Adkhul ism al-malaf:");
        String name = scan.next();
        JWorkHours2 jwh = new JWorkHours2();
        jwh.reportWorkHours(name);
    }
    //Khutwa 1: 'arraf al-tariqa allati tu3alij malaf al-muwazafeen
    public void reportWorkHours(String fileName) {
        //Khutwa 1.1: Hazir al-code alati qad turmi istithna2 dakhel kutlat try
        try {
            //Khutwa 1.1.1: Aghlif BufferedReader hawl FileReader
            FileReader fr = new FileReader(fileName); 
            BufferedReader br = new BufferedReader(fr); 
            //Khutwa 1.1.2: Istakhdim kaen BufferedReader liqira'at satr wahid fi kull marra
            String line = null;
            while ( ( line = br.readLine() ) != null) {
                String[] tokens = line.split(" ");
                //Hawel al-husul ala muarraf al-muwazzaf ka raqam
                try {
                    int eid =  Integer.parseInt(tokens[0]);
                } catch ( NumberFormatException ex) {
                    System.out.println("Khata fi muarif al-muwazzaf.");
                }
                String name = tokens[1];
                double total = 0.0;
                for (int i = 2; i < tokens.length; i++ ) {
                    try {
                        total += Double.parseDouble(tokens[i]);
                    } catch (  NumberFormatException ex ) {
                        System.out.println("Khata fi al-sa'a.");
                    }
                }
                System.out.println("Majmu al-saaat li " + name + " = " + total);
            }     
            //Khutwa 1.1.3: Aghliq kaen BufferedReader al-mutasil bil-malaf
            br.close();
        }
        //Khutwa 1.2: Taamol ma3 jami3 al-istithna2at al-mumkina allati qad turmee fi kutlat try
        catch (FileNotFoundException ex) {
            System.out.println("Al-malaf ghayr mawjud");
        }  catch (IOException ex ) {
            System.out.println("Mushkila fi al-malaf!");
        }
    }
}
